export const questOperations = {
  data: operation('Read performance spans and host process measurements for the Data page. Returns the newest rows (limit, default 500) with the total count, and the percentiles over all rows.', object({ from: number, to: number, limit: number }), [], detail, true),
  list: operation('Find Quests by text, state or project. Use view=plan for descriptions and steps in one backlog read, and view=report for the finished grouped answer (Needs you, Done — see result, Working, Queued, Done) to relay when the user asks what Quests there are. counts and scope describe every matched record, not just this page; summary omits evidence bodies.', fields.query, [], record({ items: { type: 'array', items: { anyOf: [summary, plan] } }, counts, ...boardCountFields, workers: workerCountFields, scope: text, report, total: { type: 'integer' }, nextOffset: { type: ['integer', 'null'] }, diagnostics: strings }), true),
  get: operation('Read a Quest, its steps, readiness and latest outcomes. Use inspect for one historical section. Worker completion is delivered automatically; do not poll.', object({ id: fields.id }, ['id']), ['id']),
  status: operation('Read a compact saved status and step states immediately. Includes revision; no waiting or evidence bodies.', object({ id: text }, ['id']), ['id'], status, true),
  history: operation('Read a Quest history in time order: step changes, runs and their dispatch choices, landings, host commands and exit codes, hand-offs and messages from the user, and apart from them the benches of its finished runs with route, verdict and cost. Each entry names when and where it was recorded. Missing older sources or exit codes stay unknown. Omit offset and limit for the whole history.', object({ id: text, offset: { type: 'integer', minimum: 0 }, limit: { type: 'integer', minimum: 1 } }, ['id']), ['id'], record({ id: text, items: { type: 'array', items: record({ at: text, kind: text, from: text, source: text, actor: text, directory: text, stepID: text, runID: text, state: text, model: text, route: text, why: text, method: text, branch: text, into: text, command: text, exitCode: { type: ['integer', 'null'] }, text }) }, total: { type: 'integer' }, nextOffset: { type: ['integer', 'null'] }, benches: { type: 'array', description: 'Benches of the finished runs of this Quest: the same assignment run again on a named route in a checkout of its own, scored by its checks and never landed. They are measurements, not attempts at the Quest.', items: record({ id: text, of: text, stepIDs: strings, route: text, why: text, state: text, at: text, endedAt: text, result: text, verdict: { type: ['string', 'null'] }, reasons: strings, accepted: { type: ['boolean', 'null'] }, cost: { type: 'array', items: record({ currency: text, estimate: { type: ['number', 'null'] }, actual: { type: ['number', 'null'] } }) }, requests: { type: ['integer', 'null'] }, retired: { type: 'boolean' }, retiredBecause: text }) }, diagnostics: strings }), true),
  plan: operation('Read the description, workflow, dependencies and step readiness without historical outcomes or long result notes.', object({ id: text }, ['id']), ['id'], plan, true),
  inspect: operation('Read one evidence section. Offset counts whole entries and limit targets characters, not items. Results retain complete entries.', object({ id: text, ...fields.inspect }, ['id', 'section']), ['id', 'section'], page, true),
  create: operation('Save a Quest against the Git checkout named by projectRoot, which the Quest Giver, the quest CLI and Quest MCP must always pass for a new Quest (a session opened inside a checkout defaults to it), whose task is the user\'s message saved verbatim (description is optional, only for facts the message lacks; steps are the request\'s milestones, omitted for a single action), and with start=true start it in the same call when the Quest Giver makes the call; any other caller only wakes the Quest Giver to plan and start it. Workflow model selection is optional and user controlled. Refuses a duplicate of a request an unresolved Quest already holds, and names it. Returns a decision-sized summary, not the Quest you just described.', fields.create, [], dispatched),
  update: operation('Save Quest changes. Supply at least one change alongside id; turn a Quest in with archive and restore it with reopen. Workers may update only assigned step states and notes. Agents and outside callers cannot change steps, workflow, after or projectRoot (GIVER_PLANS): the Quest Giver plans those. Returns the authoritative saved revision and the addressed steps; use get, plan or inspect only when that additional view is needed.', { ...object({ id: fields.id, ...fields.update.properties }, ['id']), minProperties: 2 }, ['id'], mutation),
  report: operation('Save one assigned step state and its evidence. A blocked step carries blocker {kind, owner, requires}; leaving blocked requires resolution {evidence} from the changed prerequisite. Save each step done as soon as it is finished, before starting the next, so the user sees progress. Any state may carry verification {command, exitCode, artifact} from a check actually run. The last step your run saves done carries result, the user\'s result card. Partial receipts are preserved independently of completion proof. Returns the authoritative saved revision, step and check receipts; workers cannot change definitions or global artifacts.', object({ id: text, stepID: text, state: { enum: ['pending', 'working', 'blocked', 'done'] }, note, blocker, resolution, verification, result: { ...resultCard, description: "With the last step your run saves done: the user's result card, from what you actually delivered, so they know what they got and how to use it. This saved result is the card." }, branches }, ['id', 'stepID', 'state', 'note']), ['id', 'stepID'], reportResult),
  archive: operation('Turn in a Quest. Accept only finished steps with no active runs; archiving unfinished work requires accepted=false and a reason.', object({ id: text, accepted: { type: 'boolean' }, reason: text }, ['id', 'accepted']), ['id'], status),
  reopen: operation('Reopen an archived Quest without losing its steps, results or history.', object({ id: text }, ['id']), ['id'], status),
  start: operation('Start a saved Quest. Only the Quest Giver starts workers: when the Quest Giver calls start, the Quest\'s planned steps start now; any other caller wakes the Quest Giver to plan the Quest and start it, and no worker starts in that call. Repeating start returns its existing request. Completion and failures arrive on their own; do not read status back.', object({ id: fields.id }, ['id']), ['id'], dispatched),
  run: operation('Quest Giver only: dispatch selected steps or a continuation with explicit run options now. Any other caller is refused with GIVER_STARTS_WORKERS; use start, which wakes the Quest Giver to plan and start the Quest.', object({ id: fields.id, ...fields.run.properties }, ['id']), ['id'], dispatched),
  wait: operation('Block until a condition holds instead of polling, then return the Quest with a compact waited block {until, satisfied, reason, runs [{runID, state, ended}], milliseconds}. To follow a run to its end use until run-ended once; do not wait again in a loop. Completion also wakes the giver automatically.', object({ id: fields.id, ...fields.wait.properties }, ['id']), ['id'], detail, true),
  stop: operation('Stop a running worker now. Records the run cancelled with the reason, then aborts its session through the host. Stops every running run of the Quest unless runID names one. The checkout and its unfinished work are kept. It needs no giver turn, so it answers while the giver is busy; workers cannot call it.', object({ id: fields.id, runID: { type: 'string', description: 'Stop only this run; omit to stop every running run of the Quest.' }, reason: { type: 'string', minLength: 1, maxLength: 2000, description: 'Why it was stopped; saved on the run.' }, order: { type: 'string', minLength: 1, maxLength: 500, description: 'The order the stop follows, such as the user\'s keep-only pause or a freeze, quoted as the user gave it. Saved on the run with the sender; omit only when no order exists.' }, sender: { type: 'string', minLength: 1, maxLength: 200, description: 'Who stopped it. Omit to record the calling session or tool.' } }, ['id']), ['id'], stopped),
  waterfall: operation('Where the time and tokens of a Quest or a time window went. One lane per Quest (journal state changes, dispatch stages), the Quest Giver and each worker session (model requests split into waiting for the first token and streaming, tools, plugin hooks, host phases); every millisecond of each lane is one span, gaps named by their boundaries, else unaccounted. Each model request carries its tokens and API-equivalent cost, and `parts` when what every prompt token was for is recorded. The default summary leaves out the spans and the token parts: view=timeline adds the spans, and request=<id> with the summary\'s window as from/to answers that one request with its parts. Name quest or from. Read-only; workers cannot call it.', waterfallInput, [], waterfallResult, true),
  succeed_giver: operation('Hand the Quest Giver role on when this giver\'s context is spent: releases the bound giver so the next Quest Giver conversation becomes it. The old conversation and its Quests are untouched. Only the bound giver can call it; workers cannot.', object({}), [], record({ released: { type: ['string', 'null'] }, next: text })),
  delivery: operation('Show how finished Quest work is delivered and where that policy came from, or set or clear it. The running host owns the settings file, so this is the one place a delivery policy is read and written. set is {into, method: pull-request|push|local-merge, landed: remote|local, retire, remote?, pullRequest?: {open: [argv], merge: [argv]}}; argv placeholders are {into} {branch} {head} {remote} {title} {body}. clear removes the saved policy so the project falls back to the one inferred from its repository. Workers cannot call it.', object({ projectRoot: { type: 'string', description: 'The project checkout whose delivery policy this names; its main checkout is used.' }, set: { type: 'object', additionalProperties: true, description: 'The delivery policy to save for the project.' }, clear: { type: 'boolean', description: 'Remove the saved policy for the project.' } }, ['projectRoot']), [], record({ project: text, settingsFile: text, policy: record({ into: text, method: { enum: ['pull-request', 'push', 'local-merge'] }, landed: { enum: ['remote', 'local'] }, retire: { type: 'boolean' }, remote: text, pullRequest: record({ open: strings, merge: strings }) }), source: { enum: ['settings', 'inferred'] }, basis: text })),
  routing: operation('Show the automatic routing settings of the running host, every route it serves now (spelled as patterns must spell them) and what each saved pattern matches, or replace them with set: the work types, and for each depth the models it never picks automatically, how much speed counts against capability and the share of runs that measures thinly evidenced routes, plus your own ratings of models per work type. Workers cannot call it.', object({ set: routingSettingsShape, allowUnserved: { ...strings, description: 'Patterns in set that may name a route not served today. Any other pattern that matches no served route is refused, naming the closest served routes. Patterns already saved at the same place are kept.' } }), [], routingResult),
  roles: operation('Show the model set for each role (front, Quest Giver, worker, model router, permission (Jev)) and where an unset one comes from, or replace them with set. A role left out of set is unset: the worker is then routed automatically, the model router and permission use their own settings files, and a role with nothing to fall back on reports that when it is needed. A set role overrides those files. Workers cannot call it.', object({ set: roleSettingsShape }), [], rolesResult),
  spend: operation('Spend the allowance on one goal until it is met or its usage target is reached. start saves the goal the user asked for: a count of Quests (ten games), a list of items (one pull request per open issue), or both, with an optional usage target {accountID, windowID, stopAtUsedPercent} and end time. While it is active you keep creating Quests toward it with create spendGoal, and every worker return shows what is left. The goal ends by itself when every item or the count has a finished Quest, or the account window reaches the target; end stops it early. Usage pacing and plan limits stay the only ceiling on workers. Without start or end it lists the goals. Workers and the front cannot change it.', object({
    start: object({ goal: { type: 'string', minLength: 1, description: 'The user\'s goal in their words.' }, projectRoot: { type: 'string', minLength: 1 }, count: { type: 'integer', minimum: 1, description: 'Finished Quests that meet the goal.' }, items: { ...strings, description: 'Distinct items that each need one finished Quest.' }, usage: object({ accountID: text, windowID: text, stopAtUsedPercent: { type: 'number', exclusiveMinimum: 0, maximum: 100 } }, ['accountID', 'windowID', 'stopAtUsedPercent']), until: { type: 'number', description: 'Unix milliseconds at which the goal stops.' } }, ['goal', 'projectRoot']),
    goalID: text, addItems: strings,
    end: object({ state: { enum: ['met', 'target reached', 'stopped'] }, reason: { type: 'string', minLength: 1 } }, ['state', 'reason']),
  }), [], record({ goals: { type: 'array', items: { type: 'object', additionalProperties: true } } })),
  owners: operation('Who owns each open Quest now: its Quest Giver and its open workers, each with the host that holds it, the active host, the current Quest Giver, and every Quest Giver or worker still away from the active host. Read from the one ownership map the hand-back and host binding use, with no model turn. Read-only; workers cannot call it.', object({}), [], readOperations.owners.output, true),
  routingMap: operation('What routing knows about every served model and effort: its published score and where it comes from; its output speed and first-token wait, measured from requests here, from one calibration request, or published, each with its source; its cost; and per work type your rating, the outcomes measured here (runs, delivered, sent back, time to finish, tokens, model calls, per depth) and the estimated time to finish a task that routing ranks speed on. Reading it sends no model request: it shows the speeds already measured or published. Workers cannot call it.', object({}), [], routingMapResult, true),
  routingHistory: operation('Past routing decisions, newest first: when, the Quest and steps, task and size, the route picked and its effort, whether routing picked it or it was chosen by name, why, what was left out and why, and how long the run took from the route being chosen to its first model request and to its end. Filter by questID or projectID; runID answers that one decision with everything it went through. New decisions arrive as routing.decided on the Quest event stream, and a decision in progress as routing.stage; do not poll. Read-only; workers cannot call it.', object({ questID: text, projectID: text, runID: text, offset: { type: 'integer', minimum: 0 }, limit: { type: 'integer', minimum: 1, maximum: 100, description: 'Decisions per page.' } }), [], routingHistoryResult, true),
  routingSimulate: operation('What routing would pick for a piece of work right now, without starting anything: it runs the same decision as a real dispatch (work profile, candidates, estimates, the model router) but reserves no route, takes no account slot, starts no worker and records nothing. The model router may really be asked to infer the work type and depth and to judge; the answer says what that cost. Use it when the user asks which model would be used for something. Workers cannot call it.', object({ text: { type: 'string', minLength: 1, maxLength: 8000, description: 'The prompt or step description to route.' }, workType: { type: 'string', description: 'One work type id from the Routing page; omit to let the model router infer it.' }, depth: { enum: depths, description: 'routine, standard, deep or frontier; omit to let the model router infer it.' }, task: { enum: ['coding', 'review', 'planning', 'utility'] } }, ['text']), [], record({ simulated: { type: 'boolean' }, at: text, runID: text, route: record({ id: text, model: text, effort: text }), reason: text, record: { type: 'object', additionalProperties: true }, decision: decisionTrace })),
  answer: operation('Answer a worker\'s pending permission ask with the user\'s decision. Quote their own words exactly as they wrote them to you since the worker asked (in Quest Web or the terminal); the host checks the quote against your conversation and records it with the reply. reply once allows that one request, reject refuses it. If the worker is no longer waiting, the ask is cleared and nothing is sent. Workers cannot call it.', object({ id: fields.id, runID: { type: 'string', description: 'The waiting run; needed only when more than one worker of the Quest waits.' }, reply: { enum: ['once', 'reject'] }, quote: { type: 'string', minLength: 1, maxLength: 2000, description: 'The user\'s words that decide the ask, verbatim.' } }, ['id', 'reply']), ['id'], record({ state: text, runID: text, ask: text, quote: text, messageID: text, note: text })),
  show_artifact: operation('Show the user a small card in the chat instead of pasting data: view quest draws one Quest (its steps, runs, verdicts and benches) from the Quest record, view usage draws the accounts and their pacing from the usage ledger, view html shows your own short HTML (headings, paragraphs, lists, tables; scripts, styles with URLs and images are removed), view needs_you draws the one card of everything only Jon can do now (worker permission asks and steps blocked on a sign-in, spend, main release, destructive action or the user\'s choice), each with the one thing the user must do; it fails with NOTHING_NEEDS_JON when nothing does, and it remembers what it showed so a check-in shows it again only when something new needs him. The chat shows the card under your answer and the tool result reads "Card shown: <title>". Workers cannot call it.', object({ view: { enum: ['quest', 'usage', 'html', 'needs_you'] }, questID: { type: 'string', description: 'The Quest to draw, for view quest.' }, title: { type: 'string', maxLength: 120, description: 'The card title; derived when omitted.' }, html: { type: 'string', maxLength: 40000, description: 'The HTML to show, for view html.' } }, ['view']), [], artifactResult),
  describe: operation('Read the whole contract of one Quest operation: its full description, its input and its output. The operation list shows each one short; use this when a short entry is not enough.', object({ operation: { type: 'string', minLength: 1 } }, ['operation']), [], record({ operation: text, description: text, input: { type: 'object', additionalProperties: true }, output: { type: 'object', additionalProperties: true } }), true),
  system_state: operation('Read all real system state in one call for a front check-in: whole-board counts and every queued Quest reason, every owned run with its exact route, host-confirmed state and minutes since its last saved step, all registered hosts with role, liveness and memory, the actual serving revision against remote v2, the reload queue, refreshed allowance windows per account, blocked steps with owners, pending permissions and questions, and allowed routes with no signed-in model match. It answers small: a head line, the counts, the serving revision against v2 and one row per host with its channel and revision. Ask for one part with section, one row per entry, and narrow runs, queued Quests, blocked steps and asks to one Quest with questID. Unknown or unavailable sources stay explicit in diagnostics; missing observations never mean healthy or zero. Does not change Quests, restart runs, reload services or message anyone. Workers cannot call it.', object({ questID: { type: 'string', minLength: 1, description: 'Only this Quest\'s queued reason, runs, blocked steps and asks; hosts, serving and accounts stay whole.' }, section: { enum: SYSTEM_STATE_SECTIONS, description: 'One part, one row per entry. Omit for the head line, counts, serving revision and hosts.' }, offset: { type: 'integer', minimum: 0 }, limit: { type: 'integer', minimum: 1, description: 'Rows of the section to show; about a page when omitted.' } }), [], systemStateResult, true),
  message: operation('Send one bounded message to the Quest Giver. Only Quest Web and connected web apps granted giver:message can send it; local terminals, the quest CLI and local Quest MCP are refused with GIVER_UNREACHABLE. It queues a giver turn — the only actor that can talk to a worker — and the answer distinguishes a host-acknowledged queue from an unconfirmed one. It is not worker execution and does not complete a step.', object({ text: { type: 'string', minLength: 1, maxLength: 4000, description: 'The message to the Quest Giver. Name the Quest or run when it matters.' }, id: { ...fields.id, description: 'Optional Quest to identify in the message; it must be readable before the message is sent.' }, images: { type: 'array', minItems: 1, items: { type: 'string', minLength: 1 }, description: 'Absolute paths of PNG, JPEG, GIF or WebP files on this computer, such as screenshots. The Quest Giver model receives each one as an image it sees itself, not a description.' }, quote: { type: 'string', minLength: 1, maxLength: 2000, description: 'The user\'s own words that this message carries, quoted exactly from a message the user wrote in this conversation. Required from a session that is not the user\'s own while self-fix is off; without it nothing is sent and the refusal is recorded on the Quest.' } }, ['text']), [], messaged),
}

const piece = (name, values, description) => { questOperations[name].input = { ...questOperations[name].input, properties: { ...questOperations[name].input.properties, view: { enum: values, description } } } }
piece('get', ['page'], 'page: what the Quest page draws: description, reward, steps with their notes and runs, pull requests and artifacts; no workflow or continuation. Omit for the small answer.')
piece('routing', ['settings'], 'settings: the saved routing settings whole, for editing them. Omit for one line per depth.')
piece('roles', ['settings'], 'settings: the saved role settings and each role whole, for editing them. Omit for one line per role.')
piece('routingHistory', ['rows', 'decision'], 'rows: each decision with the routes it passed over and left out. decision: with runID, that one decision trace. Omit for one line per decision.')
for (const name of COMPACT_QUEST_OPERATIONS) questOperations[name].input = { ...questOperations[name].input, properties: { ...questOperations[name].input.properties, full: FULL_INPUT } }

const answerRow = { type: 'object', additionalProperties: { type: ['string', 'number', 'boolean'] } }
const answerRows = { type: 'array', items: answerRow }
const answerCursor = { nextOffset: { type: ['integer', 'null'] } }
const answerCard = { quest: answerRow, steps: answerRows, runs: answerRows, result: resultCard, waited: answerRow }
const compactPages = {
  list: object({ view: { enum: ['list', 'list report', 'list board'] }, head: text, scope: text, items: answerRows, bullets: answerRows, ...answerCursor, notes: strings }, ['view', 'head']),
  get: object({ view: { const: 'get' }, head: text, ...answerCard, notes: strings }, ['view', 'head']),
  status: object({ view: { const: 'status' }, head: text, ...answerCard, notes: strings }, ['view', 'head']),
  inspect: object({ view: { const: 'inspect' }, head: text, items: answerRows, fields: answerRows, text, ...answerCursor, notes: strings }, ['view', 'head']),
  history: object({ view: { const: 'history' }, head: text, items: answerRows, earlierCount: { type: 'integer' }, ...answerCursor, notes: strings }, ['view', 'head']),
  routing: object({ view: { const: 'routing' }, head: text, depths: answerRows, notes: strings }, ['view', 'head']),
  routingHistory: object({ view: { const: 'routingHistory' }, head: text, items: answerRows, ...answerCursor, notes: strings }, ['view', 'head']),
  roles: object({ view: { const: 'roles' }, head: text, roles: answerRows, notes: strings }, ['view', 'head']),
  waterfall: object({ view: { const: 'waterfall' }, head: text, lanes: answerRows, notes: strings }, ['view', 'head']),
  system_state: object({ view: { enum: ['system_state', 'system_state section'] }, head: text, counts: answerRow, serving: answerRow, hosts: answerRows, items: answerRows, ...answerCursor, notes: strings }, ['view', 'head']),
}
for (const [name, compact] of Object.entries(compactPages)) questOperations[name].output = { type: 'object', anyOf: [compact, { ...questOperations[name].output, not: { required: ['head'] } }] }

const SHORT_TEXT = 240

const shortText = value => {
  const text = String(value ?? '')
  if (text.length <= SHORT_TEXT) return text
  const sentence = text.slice(0, SHORT_TEXT).replace(/\s+\S*$/, '')
  const end = Math.max(sentence.lastIndexOf('. '), sentence.lastIndexOf('; '))
  return (end > 60 ? sentence.slice(0, end + 1) : sentence + '...')
}

const shortSchema = (schema, seen = new Set()) => {
  if (Array.isArray(schema)) return schema.map(item => shortSchema(item, seen))
  if (!schema || typeof schema !== 'object') return schema
  return Object.fromEntries(Object.entries(schema).flatMap(([key, value]) => {
    if (key === 'description' && typeof value === 'string') return seen.has(value) ? [] : (seen.add(value), [[key, shortText(value)]])
    if (key === 'properties' && value && typeof value === 'object') return [[key, shortSchema(Object.fromEntries(Object.entries(value).filter(([, property]) => property !== FULL_INPUT)), seen)]]
    return [[key, shortSchema(value, seen)]]
  }))
}

export function questTools(operations = questOperations) {
  return Object.entries(operations).map(([name, op]) => ({ name, description: shortText(op.description) + (op.description.length > SHORT_TEXT ? ' Call describe for the whole contract.' : ''), inputSchema: shortSchema(op.input), annotations: op.annotations }))
}

export function describeOperation(name, operations = questOperations) {
  const op = Object.hasOwn(operations, name) ? operations[name] : undefined
  if (!op) return undefined
  return { operation: name, description: op.description, input: op.input, output: op.output }
}

export function coordinatorInput(method, input) {
  const { id, ...value } = input
  if (method === 'status' || method === 'plan') return { action: 'get', id }
  if (method === 'inspect') return { action: 'get', id, inspect: value }
  if (method === 'report') return { action: 'update', id, update: { steps: [{ id: value.stepID, state: value.state, note: value.note, ...(value.blocker === undefined ? {} : { blocker: value.blocker }), ...(value.resolution === undefined ? {} : { resolution: value.resolution }), ...(value.verification === undefined ? {} : { verification: value.verification }), ...(value.result === undefined ? {} : { result: value.result }), ...(value.branches === undefined ? {} : { branches: value.branches }) }] } }
  if (method === 'archive') return { action: 'update', id, update: { archive: value } }
  if (method === 'reopen') return { action: 'update', id, update: { archive: null } }
  if (method === 'list') return { action: method, query: value }
  if (method === 'create') return { action: method, create: value }
  if (method === 'get' || method === 'start') return { action: method, ...input }
  return { action: method, id, [method]: value }
}
